import React,{useState}from'react';import{createRoot}from'react-dom/client';import'./styles.css';
const stops=[['North Gate','2 min','Blue line'],['Library Loop','8 min','Blue line'],['Science Park','14 min','Green line'],['Arts Block','21 min','Green line']];
function App(){const[stop,setStop]=useState(stops[0][0]),[tab,setTab]=useState('Live');return <main><header><div className="brand"><span className="logo">↗</span><div><b>HopOn</b><small>Campus shuttle</small></div></div><span className="status">● All routes running</span><button className="avatar">AJ</button></header><section className="hero"><p className="eyebrow">MONDAY · 8:42 AM</p><h1>Move around<br/><em>with certainty.</em></h1><p className="muted">Real-time arrivals for every campus shuttle.</p></section><div className="selectrow"><label>Starting from<select value={stop} onChange={e=>setStop(e.target.value)}>{stops.map(s=><option key={s[0]}>{s[0]}</option>)}</select></label><button className="swap">⇄</button><label>Going to<select><option>Central Library</option><option>Student Centre</option><option>Residence Hall</option></select></label></div><section className="card next"><div><span className="eyebrow">NEXT SHUTTLE · {stop}</span><h2>Blue line <b>in 2 min</b></h2><p className="muted">Arriving at North Gate · 8:44 AM</p></div><div className="bus">▣</div></section><div className="alert"><span>!</span><p><b>Service update</b><br/>Green line is running 5 minutes late due to construction.</p><button>×</button></div><nav className="tabs">{['Live','Route map','Timetable'].map(x=><button className={tab===x?'selected':''} onClick={()=>setTab(x)} key={x}>{x}</button>)}</nav>{tab==='Live'&&<div className="arrivals">{stops.map(s=><article className="card arrival" key={s[0]}><span className="routepill">{s[2][0]}</span><div><h2>{s[0]}</h2><small>{s[2]} · Every 15 min</small></div><strong>{s[1]}</strong><span>min</span></article>)}</div>}{tab==='Route map'&&<div className="card map"><div className="line blue"/><div className="line green"/>{stops.map((s,i)=><div className={'mapstop s'+i} key={s[0]}><i/>{s[0]}</div>)}</div>}{tab==='Timetable'&&<div className="card timetable"><h2>Blue line · North Gate</h2>{['8:44 AM','8:59 AM','9:14 AM','9:29 AM'].map(x=><div><span>{x}</span><b>Central Library</b></div>)}</div>}</main>}createRoot(document.getElementById('root')).render(<App/>);
